/* HEXA BATTLEGROUNDS setup — PART 76 OF 82. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-qwerty-18', 'qwerty', 'mission', 'Keyboard Cipher', 'cipher', 2, array['office','learning','helpdesk','stg','any']::text[], 'A message was typed with the hands in the wrong place on the keyboard. Scout has the message, Intel knows how far the hands slipped, Decoder has the keyboard.', '{"scout":{"title":"Scrambled message","body":"BDZUTTZ","big":true},"intel":{"title":"Where the hands were","body":"The typist''s hands were 2 keys to the RIGHT of where they should be, on the same row. Each row wraps around at the ends."},"decoder":{"title":"The keyboard","body":"Top row:     Q W E R T Y U I O P\nMiddle row:  A S D F G H J K L\nBottom row:  Z X C V B N M"}}'::jsonb, '[{"label":"The real word","accept":["CANTEEN"]}]'::jsonb, false, 3, 200, 'For each letter, find it on Decoder''s keyboard and move back the other way.', 'BDZUTTZ shifted -2 → CANTEEN', null, 25, 'published'), ('mission-qwerty-19', 'qwerty', 'mission', 'Keyboard Cipher', 'cipher', 2, array['office','learning','helpdesk','stg','any']::text[], 'A message was typed with the hands in the wrong place on the keyboard. Scout has the message, Intel knows how far the hands slipped, Decoder has the keyboard.', '{"scout":{"title":"Scrambled message","body":"IKWHYVD","big":true},"intel":{"title":"Where the hands were","body":"The typist''s hands were 2 keys to the LEFT of where they should be, on the same row. Each row wraps around at the ends."},"decoder":{"title":"The keyboard","body":"Top row:     Q W E R T Y U I O P\nMiddle row:  A S D F G H J K L\nBottom row:  Z X C V B N M"}}'::jsonb, '[{"label":"The real word","accept":["PARKING"]}]'::jsonb, false, 3, 200, 'For each letter, find it on Decoder''s keyboard and move back the other way.', 'IKWHYVD shifted 2 → PARKING', null, 25, 'published'), ('battle-qwerty-40', 'qwerty', 'battle', 'Keyboard Cipher', 'cipher', 1, array['duel_smg']::text[], 'A message was typed with the hands in the wrong place on the keyboard. Scout has the message, Intel knows how far the hands slipped, Decoder has the keyboard.', '{"scout":{"title":"Scrambled message","body":"XLXGW","big":true},"intel":{"title":"Where the hands were","body":"The typist''s hands were 1 key to the LEFT of where they should be, on the same row. Each row wraps around at the ends."},"decoder":{"title":"The keyboard","body":"Top row:     Q W E R T Y U I O P\nMiddle row:  A S D F G H J K L\nBottom row:  Z X C V B N M"}}'::jsonb, '[{"label":"The real word","accept":["CACHE"]}]'::jsonb, false, 3, 90, 'For each letter, find it on Decoder''s keyboard and move back the other way.', 'XLXGW shifted 1 → CACHE', null, 25, 'published'), ('battle-qwerty-41', 'qwerty', 'battle', 'Keyboard Cipher', 'cipher', 1, array['duel_smg']::text[], 'A message was typed with the hands in the wrong place on the keyboard. Scout has the message, Intel knows how far the hands slipped, Decoder has the keyboard.', '{"scout":{"title":"Scrambled message","body":"LRTMRA","big":true},"intel":{"title":"Where the hands were","body":"The typist''s hands were 1 key to the RIGHT of where they should be, on the same row. Each row wraps around at the ends."},"decoder":{"title":"The keyboard","body":"Top row:     Q W E R T Y U I O P\nMiddle row:  A S D F G H J K L\nBottom row:  Z X C V B N M"}}'::jsonb, '[{"label":"The real word","accept":["KERNEL"]}]'::jsonb, false, 3, 90, 'For each letter, find it on Decoder''s keyboard and move back the other way.', 'LRTMRA shifted -1 → KERNEL', null, 25, 'published'), ('battle-qwerty-42', 'qwerty', 'battle', 'Keyboard Cipher', 'cipher', 1, array['duel_smg']::text[], 'A message was typed with the hands in the wrong place on the keyboard. Scout has the message, Intel knows how far the hands slipped, Decoder has 