inct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now(); insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-clock2-0', 'worldclock', 'mission', 'World Clock', 'maths', 1, array['boardroom','office','public','coffee','any']::text[], 'A client call is booked from Siruseri. Scout has the time in India, Intel knows where the client sits, Decoder has the time offsets. What time is it for the client?', '{"scout":{"title":"Call time in India (IST)","body":"08:00","big":true},"intel":{"title":"Client office","body":"The client joins from London."},"decoder":{"title":"Offsets from UTC (use exactly these)","body":"India (IST) = UTC +5:30\nLondon = UTC +0\nNew York = UTC −5\nDubai = UTC +4\nSingapore = UTC +8\nSydney = UTC +11\nFrankfurt = UTC +1\nToronto = UTC −5\nTokyo = UTC +9\nJohannesburg = UTC +2\nChicago = UTC −6"}}'::jsonb, '[{"label":"Client''s local time (24-hour, HH:MM)","accept":["0230"]}]'::jsonb, false, 3, 200, 'Go from IST to UTC first (subtract 5 h 30 min), then add the client''s offset. Wrap past midnight.', '08:00 IST → London 02:30', null, 25, 'published'), ('mission-clock2-1', 'worldclock', 'mission', 'World Clock', 'maths', 2, array['boardroom','office','public','coffee','any']::text[], 'A client call is booked from Siruseri. Scout has the time in India, Intel knows where the client sits, Decoder has the time offsets. What time is it for the client?', '{"scout":{"title":"Call time in India (IST)","body":"08:00","big":true},"intel":{"title":"Client office","body":"The client joins from New York."},"decoder":{"title":"Offsets from UTC (use exactly these)","body":"India (IST) = UTC +5:30\nLondon = UTC +0\nNew York = UTC −5\nDubai = UTC +4\nSingapore = UTC +8\nSydney = UTC +11\nFrankfurt = UTC +1\nToro